        #[test]
        fn bindgen_test_layout_ModCallbackEvent() {
            const UNINIT: ::std::mem::MaybeUninit<ModCallbackEvent> =
                ::std::mem::MaybeUninit::uninit();
            let ptr = UNINIT.as_ptr();
            assert_eq!(
                ::std::mem::size_of::<ModCallbackEvent>(),
                32usize,
                concat!("Size of: ", stringify!(ModCallbackEvent))
            );
            assert_eq!(
                ::std::mem::align_of::<ModCallbackEvent>(),
                8usize,
                concat!("Alignment of ", stringify!(ModCallbackEvent))
            );
            assert_eq!(
                unsafe { ::std::ptr::addr_of!((*ptr).eventName) as usize - ptr as usize },
                0usize,
                concat!(
                    "Offset of field: ",
                    stringify!(ModCallbackEvent),
                    "::",
                    stringify!(eventName)
                )
            );
            assert_eq!(
                unsafe { ::std::ptr::addr_of!((*ptr).strArg) as usize - ptr as usize },
                8usize,
                concat!(
                    "Offset of field: ",
                    stringify!(ModCallbackEvent),
                    "::",
                    stringify!(strArg)
                )
            );
            assert_eq!(
                unsafe { ::std::ptr::addr_of!((*ptr).numArg) as usize - ptr as usize },
                16usize,
                concat!(
                    "Offset of field: ",
                    stringify!(ModCallbackEvent),
                    "::",
                    stringify!(numArg)
                )
            );
            assert_eq!(
                unsafe { ::std::ptr::addr_of!((*ptr).sender) as usize - ptr as usize },
                24usize,
                concat!(
                    "Offset of field: ",
                    stringify!(ModCallbackEvent),
                    "::",
                    stringify!(sender)
                )
            );
        }
