        #[derive(Debug, Copy, Clone, Hash, PartialOrd, Ord, PartialEq, Eq)]
        pub struct BSCriticalSection {
            pub criticalSection: root::SKSE::WinAPI::CRITICAL_SECTION,
        }
        #[test]
        fn bindgen_test_layout_BSCriticalSection() {
            const UNINIT: ::std::mem::MaybeUninit<BSCriticalSection> =
                ::std::mem::MaybeUninit::uninit();
            let ptr = UNINIT.as_ptr();
            assert_eq!(
                ::std::mem::size_of::<BSCriticalSection>(),
                40usize,
                concat!("Size of: ", stringify!(BSCriticalSection))
            );
            assert_eq!(
                ::std::mem::align_of::<BSCriticalSection>(),
                8usize,
                concat!("Alignment of ", stringify!(BSCriticalSection))
            );
            assert_eq!(
                unsafe { ::std::ptr::addr_of!((*ptr).criticalSection) as usize - ptr as usize },
                0usize,
                concat!(
                    "Offset of field: ",
                    stringify!(BSCriticalSection),
                    "::",
                    stringify!(criticalSection)
                )
            );
        }
