        #[test]
        fn bindgen_test_layout_BGSDecalNode_RUNTIME_DATA() {
            const UNINIT: ::std::mem::MaybeUninit<BGSDecalNode_RUNTIME_DATA> =
                ::std::mem::MaybeUninit::uninit();
            let ptr = UNINIT.as_ptr();
            assert_eq!(
                ::std::mem::size_of::<BGSDecalNode_RUNTIME_DATA>(),
                32usize,
                concat!("Size of: ", stringify!(BGSDecalNode_RUNTIME_DATA))
            );
            assert_eq!(
                ::std::mem::align_of::<BGSDecalNode_RUNTIME_DATA>(),
                8usize,
                concat!("Alignment of ", stringify!(BGSDecalNode_RUNTIME_DATA))
            );
            assert_eq!(
                unsafe { ::std::ptr::addr_of!((*ptr).decals) as usize - ptr as usize },
                0usize,
                concat!(
                    "Offset of field: ",
                    stringify!(BGSDecalNode_RUNTIME_DATA),
                    "::",
                    stringify!(decals)
                )
            );
            assert_eq!(
                unsafe { ::std::ptr::addr_of!((*ptr).isSkinned) as usize - ptr as usize },
                24usize,
                concat!(
                    "Offset of field: ",
                    stringify!(BGSDecalNode_RUNTIME_DATA),
                    "::",
                    stringify!(isSkinned)
                )
            );
        }
