    #[repr(C)]
    #[derive(Debug, Hash, PartialOrd, Ord, PartialEq, Eq)]
    pub struct Node {
        pub item: root::value_type,
        pub next: root::SKSE::stl::observer,
        pub __bindgen_padding_0: u64,
    }
    #[test]
    fn bindgen_test_layout_Node() {
        const UNINIT: ::std::mem::MaybeUninit<Node> = ::std::mem::MaybeUninit::uninit();
        let ptr = UNINIT.as_ptr();
        assert_eq!(
            ::std::mem::size_of::<Node>(),
            16usize,
            concat!("Size of: ", stringify!(Node))
        );
        assert_eq!(
            ::std::mem::align_of::<Node>(),
            8usize,
            concat!("Alignment of ", stringify!(Node))
        );
        assert_eq!(
            unsafe { ::std::ptr::addr_of!((*ptr).item) as usize - ptr as usize },
            0usize,
            concat!(
                "Offset of field: ",
                stringify!(Node),
                "::",
                stringify!(item)
            )
        );
        assert_eq!(
            unsafe { ::std::ptr::addr_of!((*ptr).next) as usize - ptr as usize },
            8usize,
            concat!(
                "Offset of field: ",
                stringify!(Node),
                "::",
                stringify!(next)
            )
        );
    }
